from heapq import heappush, heappop

# Function to solve the problem
def count_close_pairs(n, l, w):
    # Build the graph as an adjacency list
    graph = defaultdict(list)
    for _ in range(n - 1):
        pi, wi = map(int, input().split())
        a, b, c, d = pi, wi, pi, wi
        # Adjust the weight and apply the rubber band principle
        if b != a:
            if c > wi or d > w:
                heappush(graph[a], [d])
            elif c > wi or d > w:
                heappush(graph[b], [d])
            else:
                max_heap = heappop(graph[a]) + heappop(graph[b])
                if max(max_heap[0], max_heap[1]) > max(max(c, d), max_heap[-1]):
                    heappush(graph[b], max_heap)
    # Calculate the number of close pairs
    return sum(inter for e in graph for inter in intersect(e) for i in range(len(inter) - 1))

# Function to calculate the intersect of two lists of weights which represent paths of a single step shorter
def intersect(edge):
    left, right = 0, len(edge)
    for i in range(right - 1, 0, -1):
        while right >= i and (edge[right][1] - edge[left][1]) + (edge[i][0] - edge[right][0]) > l:
            right -= 1
        yield [edge[left][1], edge[right][1], edge[right][0] - edge[left][0], edge[i][0] - edge[left][0]]

