# calculate damage when using only fire-towers
def fire_only(df, rf):
    total_damage = 0
    for r in [rf, rf, rf]:
        for d in [df, df, df]:
            if r <= r + math.sqrt(d * de):
                total_damage += d
                break
    return total_damage

# calculate damage when using one freezing tower
def freezing_once(rs, rf):
    total_damage = 0
    for r in [rs, rf, rf]:
        for d in [df, df, df]:
            if r <= r + math.sqrt(d * de):
                if r == rf:
                    total_damage += df
                else:
                    total_damage += d
                break
    return total_damage

# calculate damage when using both freezing towers counter-clockwise
def freezing_double(rf, rs):
    total_damage = 0
    for i in range(3):
        for j in range(3):
            total_damage += max(df, de)
            if i == 0:
                r1 = math.sqrt(rs ** 2 - (1 - 2 * math.cos(0 * math.pi/3)) * rs ** 2)
            elif j == 0:
                r1 = math.sqrt(rs ** 2 - (1 + 2 * math.cos(0 * math.pi/3)) * rs ** 2)
            elif i == 1:
                r2 = math.sqrt(rs ** 2 - (1 - 2 * math.cos(60 * math.pi/3)) * rs ** 2)
            else:
                r2 = math.sqrt(rs ** 2 - (1 + 2 * math.cos(60 * math.pi/3)) * rs ** 2)
            if max_r := rf <= max(r1, r2):
                total_damage += df
            elif r1 <= rs + r2 + math.sqrt(df * de) and r1 <= rs + rf + math.sqrt(df * de):
                total_damage += de
            break
    return total_damage

