from collections import defaultdict

def findPortal(n, rows, cols):
    rows.sort()
    cols.sort()

    if rows != list(range(1, n+1)) or cols != list(range(1, n+1)):
        return [-1]

    m, portals = 0, []
    visited = [[False] * n for _ in range(n)]
    directions = [[0, 1], [1, 0], [0, -1], [-1, 0]]

    for i in range(n):
        for j in range(n):
            if visited[i][j]:
                continue
            path = []
            x, y = i, j
            for dx, dy, dir in directions:
                tx, ty = x + dx, y + dy
                if tx < 0 or tx == n or ty < 0 or ty == n:
                    break
                while visited[tx][ty]:
                    x, y = tx, ty
                    tx, ty = tx + dx, ty + dy
                if visited[tx][ty]:
                    break
                path.append((x, y + dy, x, ty))
                path.append((ty, x + dx, y, x))

            visited[i][j] = True
            for x, y, nx, ny in path:
                portals.append([x, y, nx, ny])

    return [1, " ".join(map(str, portals))]

