def calculate_win(x1, x2, a, b):
    """
    Determines the winner of the fencing match considering optimal play.
    If the first player wins, returns the optimal winning move.
    """
    if x1 - x2 + 1 >= b or x2 - x1 + 1 >= b:
        return "DRAW"
    if x1 - x2 + 1 == b or x2 - x1 + 1 == b:
        return "FIRST" if x2 > x1 else "SECOND"

    # Check for second and first winner
    for i in range(b, a-1, -1):
        if x2 - i + 1 > b:
            first_winner = x1 + i
            break
    else:
        first_winner = x1 + (b + 1)
    for i in range(a, b + 1):
        if x1 - i + 1 > b:
            second_winner = x2 + i
            break
    else:
        second_winner = x2 + (b + 1)

    if second_winner > first_winner:
        return "SECOND"
    return "FIRST"

