def comb(n, k):
    """Binomial coefficient (also called the "n choose k" coefficient)"""
    return factorial(n) // (factorial(k) * factorial(n - k))

@lru_cache(maxsize=None)
def factorial(x):
    if x == 0:
        return 1
    return factors(x)

@lru_cache(maxsize=None)
def factors(n):
    """Find the prime factors of n as a list (same order as the usual convention)"""
    factors = set()
    factors.add(n)
    div = 2
    max_n = int(n**0.5)+1
    while n > 1 and div <= max_n:
        if n % div == 0:
            factors.add(div)
            n = n div
        else:
            div += 1
    if n > 1:
        factors.add(n)
    return sorted(list(factors))

