def largest_piece(length, parts, pieces, k):
    total_sum = sum(x[i] for x in parts)
    requirements = [0] * k
    new_piece_start = []

    def update():
        for i in reversed(range(k)):
            if requirements[i] < total_sum - requirements[i]:
                return False
            requirements[i] -= (total_sum - requirements[i]) % (1<<i) 
        for i in range(k-1, -1, -1):
            if (total_sum - requirements[i]) // (1 << i) == requirements[i]:
                new_piece_start = [requirements[i] // (1<<i), i]
                return True
        return False
    pieces.sort()
    new_piece_start = []
    chunks = chain.from_iterable(pieces[i] for i in range(k) if update())
    for start in chunks:
        for piece_start in new_piece_start:
            for piece in parts[piece_start-1]:
                if piece[1] < start:
                    continue
                piece[1] -= start
                piece[0] -= piece[1] // length
                piece[1] %= length
    return len(chunks)

