    candidates = sorted(list(map(int, input().split())))
    result = 0

    for i, a_i in enumerate(candidates):
        if a_i < X:
            continue
        for j, a_j in enumerate(candidates[i:], i + 1):
            if a_j < X:
                continue
            if math.gcd(a_i, X) == X and math.lcm(a_j, Y) == Y:
                result += 1

    return result

