from functools import lru_cache


@lru_cache(None)
def permutations_modulo_catalan(n, modulo):
    if n <= 2:
        return n

    result = (n * permutations_modulo_catalan(n - 1, modulo) - permutations_modulo_catalan(n - 2, modulo)) % modulo
    return (result + modulo) % modulo


@lru_cache(None)
def find_k_consecutive(n, k, modulo):
    if n <= 2:
        return n

    factorial_n_minus_1 = 1
    factorial_k = 1
    for i in range(1, n - k + 1):
        factorial_n_minus_1 *= i
    for i in range(k):
        factorial_k *= i + 2

    for last in range(1, n - 1):
        result = (last * permutations_modulo_catalan(last - 1, modulo) - n + 1) % modulo
        for i in range(1, last - 1):
